'use strict';
const fighters=[
 {id:'birrow',name:'BIRROW',place:'Ocean Drive',style:'RITMO · VELOCIDADE',x:63,y:40,face:14.5},
 {id:'hector',name:'MEU PATRON',place:'Coral Gables',style:'KICKBOXING · GRAVES',x:34,y:39,face:38.2},
 {id:'halfred',name:'HALFRED',place:'Coral Way',style:'ENERGIA · ARRANCADA',x:38,y:34,face:61.8},
 {id:'cesar',name:'CESAR',place:'Coconut Grove',style:'ALCANCE · HARMONIA',x:41,y:48,face:85.3}
];
const $=id=>document.getElementById(id),music=window.arcadeAudio,reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
let state='studio',selected=0,busy=false,introTimer;const cpuIndex=()=>selected===2?0:2;
const portraitFiles=['birrow-portrait.png','patron-portrait.png','halfred-portrait.png','cesar-portrait.png'];
function updateAudioLabel(){const s=music.status();$('sound').textContent=s.enabled?(s.context==='running'?'SOM: ON':'SOM: ATIVAR'):'SOM: OFF';$('sound').setAttribute('aria-pressed',String(s.enabled));}
async function unlock(){await music.unlock();updateAudioLabel();}
function effect(kind){unlock().then(()=>music.effect(kind));}
document.addEventListener('pointerdown',e=>{if(!e.target.closest('#sound'))unlock();},{capture:true});
document.addEventListener('keydown',()=>unlock(),{capture:true});
function transition(next){if(busy||next===state)return;busy=true;clearTimeout(introTimer);if(state==='fight'&&next!=='fight')window.fightEngine.stop();$('curtain').classList.add('closed');setTimeout(()=>{document.querySelectorAll('.screen').forEach(el=>el.hidden=el.id!==next);state=next;$('game').dataset.screen=next;music.setScene(next);$('curtain').classList.remove('closed');if(next==='select')render();if(next==='fight')window.fightEngine.start();setTimeout(()=>{busy=false;if(next==='select')document.querySelector('.card.selected').focus({preventScroll:true});if(next==='ready')$('fight-now').focus({preventScroll:true});},reduced?0:460)},reduced?0:460)}
function render(){const f=fighters[selected],cpu=fighters[cpuIndex()];$('fighter-name').textContent=f.name;$('cpu-name').textContent=cpu.name;$('fighter-style').textContent=f.style;$('location-name').textContent=f.place;const left=$('player-portrait');left.hidden=false;left.style.backgroundImage=`url('assets/${portraitFiles[selected]}')`;left.setAttribute('aria-label',f.name);const right=$('cpu-portrait');right.hidden=false;right.style.backgroundImage=`url('assets/${portraitFiles[cpuIndex()]}')`;right.setAttribute('aria-label',cpu.name);document.querySelectorAll('.card').forEach((e,i)=>{e.classList.toggle('selected',i===selected);e.classList.toggle('cpu-target',i===cpuIndex());e.setAttribute('aria-pressed',String(i===selected));e.tabIndex=i===selected?0:-1});document.querySelectorAll('.pin').forEach((e,i)=>e.classList.toggle('active',i===selected));$('live').textContent=f.name+' — '+f.place+'. Adversário: '+cpu.name+', controlado pela máquina.';}
function choose(i){if(busy)return;selected=(i+fighters.length)%fighters.length;render();effect('move');}
function confirm(){if(busy)return;const f=fighters[selected],cpu=fighters[cpuIndex()];$('ready-name').textContent=f.name;$('ready-cpu').textContent=cpu.name+' · CPU';$('ready-location').textContent=f.place;const playable=selected===0;$('ready-copy').textContent=playable?'Velocidade e Batida Neon contra as investidas elétricas de Halfred.':'Este lutador está na seleção; a primeira luta jogável desta versão é Birrow contra Halfred.';$('fight-now').hidden=!playable;effect('confirm');transition('ready');}
fighters.forEach((f,i)=>{const b=document.createElement('button');b.className='card';b.setAttribute('aria-label',f.name+' — '+f.place);b.innerHTML='<span class="name">'+f.name+'</span>';b.onclick=()=>choose(i);$('roster').append(b);const p=document.createElement('button');p.className='pin';p.style.left=f.x+'%';p.style.top=f.y+'%';p.setAttribute('aria-label',f.place+' — selecionar '+f.name);p.innerHTML='<span>'+f.place+'</span>';p.onclick=()=>choose(i);$('pins').append(p)});
Promise.all(['studio','title','title-clean','select-clean','select','ocean-drive'].map(n=>new Promise(resolve=>{const im=new Image();im.onload=resolve;im.onerror=resolve;im.src='assets/'+n+'.png'}))).then(()=>{if(state==='studio'&&!busy)introTimer=setTimeout(()=>transition('title'),2800)});
$('skip').onclick=()=>{effect('open');transition('title')};$('start').onclick=()=>{effect('start');transition('select')};$('back').onclick=()=>{effect('back');transition('title')};$('confirm').onclick=confirm;$('fight-now').onclick=()=>{effect('start');transition('fight')};$('fight-exit').onclick=()=>transition('select');$('choose-again').onclick=()=>{effect('back');transition('select')};$('sound').onclick=async()=>{if(music.enabled&&music.status().context!=='running')await unlock();else await music.toggle();updateAudioLabel();if(music.enabled)music.effect('open')};
$('fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch{$('fullscreen').textContent='INDISPONÍVEL'}};
function openControls(){effect('open');$('controls-dialog').showModal();}function closeControls(){$('controls-dialog').close();effect('back');}
$('controls').onclick=openControls;$('view-controls').onclick=openControls;$('close-controls').onclick=closeControls;$('controls-dialog').addEventListener('cancel',()=>music.effect('back'));
 document.addEventListener('keydown',e=>{if(e.repeat||busy||$('controls-dialog').open)return;const key=e.key;if(state==='fight'&&key==='Escape'){e.preventDefault();transition('select');return}if(!['Enter','Escape','ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(key))return;if(key==='Enter'&&e.target.closest('button')&&!e.target.closest('.card'))return;e.preventDefault();if(state==='studio'&&key==='Enter'){effect('open');transition('title')}else if(state==='title'&&key==='Enter'){effect('start');transition('select')}else if(state==='select'){if(key.startsWith('Arrow')){choose(selected+(['ArrowLeft','ArrowUp'].includes(key)?-1:1));document.querySelector('.card.selected').focus({preventScroll:true})}if(key==='Enter')confirm();if(key==='Escape'){effect('back');transition('title')}}else if(state==='ready'){if(key==='Enter'&&selected===0)transition('fight');if(key==='Escape'){effect('back');transition('select')}}});
render();$('game').dataset.screen=state;
window.arcadeDebug={getState:()=>({screen:state,selected:fighters[selected].name,cpu:fighters[cpuIndex()].name,arena:fighters[selected].place,busy,audio:music.status(),controlsOpen:$('controls-dialog').open,fight:window.fightEngine.status()})};
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'get_game_status',description:'Consulta tela, jogador, adversário da máquina, arena e estado do som.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>window.arcadeDebug.getState()})).catch(()=>{});}catch{}}
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'select_fighter',title:'Selecionar lutador',description:'Seleciona o lutador do jogador único. O adversário é a máquina; não inicia combate.',inputSchema:{type:'object',properties:{fighter:{type:'string',enum:fighters.map(f=>f.name)}},required:['fighter'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){const i=fighters.findIndex(f=>f.name===input?.fighter);if(i<0)throw new Error('Lutador inválido');if(state!=='select'||busy)throw new Error('Abra a seleção e aguarde a transição');choose(i);return{fighter:fighters[selected].name,arena:fighters[selected].place,cpu:fighters[cpuIndex()].name};}})).catch(()=>{});}catch{}}
